-- Versioned workflow definitions, immutable instance snapshots, approvals, and rejection history.
ALTER TABLE users ADD COLUMN skills_json TEXT;
CREATE TABLE IF NOT EXISTS workflow_definitions (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, applies_to TEXT NOT NULL CHECK (applies_to IN ('normal','critical')), version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0), is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)), created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE (code, version));
CREATE TABLE IF NOT EXISTS workflow_steps (id INTEGER PRIMARY KEY AUTOINCREMENT, definition_id INTEGER NOT NULL REFERENCES workflow_definitions(id) ON DELETE CASCADE, step_key TEXT NOT NULL, label TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('employee','supervisor','manager','admin')), step_order INTEGER NOT NULL CHECK (step_order > 0), is_required INTEGER NOT NULL DEFAULT 1 CHECK (is_required IN (0,1)), approval_type TEXT NOT NULL CHECK (approval_type IN ('none','review','approval','closure')), sla_seconds INTEGER CHECK (sla_seconds IS NULL OR sla_seconds > 0), UNIQUE (definition_id, step_order), UNIQUE (definition_id, step_key));
CREATE TABLE IF NOT EXISTS workflow_instances (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL UNIQUE REFERENCES tasks(id) ON DELETE CASCADE, definition_id INTEGER REFERENCES workflow_definitions(id) ON DELETE SET NULL, definition_code TEXT NOT NULL, definition_version INTEGER NOT NULL, definition_snapshot TEXT NOT NULL, current_step_order INTEGER NOT NULL CHECK (current_step_order > 0), status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','REJECTED','COMPLETED','CANCELLED')), created_by INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), completed_at TEXT);
CREATE TABLE IF NOT EXISTS workflow_actions (id INTEGER PRIMARY KEY AUTOINCREMENT, instance_id INTEGER NOT NULL REFERENCES workflow_instances(id) ON DELETE CASCADE, step_order INTEGER NOT NULL CHECK (step_order > 0), action TEXT NOT NULL CHECK (action IN ('SUBMITTED','APPROVED','REJECTED','CLOSED')), previous_state TEXT NOT NULL, next_state TEXT NOT NULL, reason TEXT, actor_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT, acted_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_workflow_steps_definition_order ON workflow_steps(definition_id, step_order);
CREATE INDEX IF NOT EXISTS idx_workflow_instances_status ON workflow_instances(status, current_step_order);
CREATE INDEX IF NOT EXISTS idx_workflow_actions_instance_time ON workflow_actions(instance_id, acted_at);
INSERT INTO workflow_definitions (code, name, applies_to, version, is_active) SELECT 'normal-task-v1', 'Normal Task', 'normal', 1, 1 WHERE NOT EXISTS (SELECT 1 FROM workflow_definitions WHERE code = 'normal-task-v1' AND version = 1);
INSERT INTO workflow_steps (definition_id, step_key, label, role, step_order, is_required, approval_type) SELECT id, 'employee-complete', 'Employee', 'employee', 1, 1, 'none' FROM workflow_definitions WHERE code = 'normal-task-v1' AND version = 1 AND NOT EXISTS (SELECT 1 FROM workflow_steps s WHERE s.definition_id = workflow_definitions.id);
INSERT INTO workflow_steps (definition_id, step_key, label, role, step_order, is_required, approval_type) SELECT id, 'completed', 'Completed', 'employee', 2, 1, 'closure' FROM workflow_definitions WHERE code = 'normal-task-v1' AND version = 1 AND NOT EXISTS (SELECT 1 FROM workflow_steps s WHERE s.definition_id = workflow_definitions.id AND s.step_order = 2);
