INSERT INTO workflow_steps (definition_id, step_key, label, role, step_order, is_required, approval_type) SELECT id, 'manager-approval', 'Manager Approval', 'manager', 3, 1, 'approval' FROM workflow_definitions WHERE code = 'critical-finding-v1' AND version = 1 AND NOT EXISTS (SELECT 1 FROM workflow_steps s WHERE s.definition_id = workflow_definitions.id AND s.step_order = 3);
INSERT INTO workflow_steps (definition_id, step_key, label, role, step_order, is_required, approval_type) SELECT id, 'closed', 'Closed', 'manager', 4, 1, 'closure' FROM workflow_definitions WHERE code = 'critical-finding-v1' AND version = 1 AND NOT EXISTS (SELECT 1 FROM workflow_steps s WHERE s.definition_id = workflow_definitions.id AND s.step_order = 4);
